import type { Decimals, Dnum, Numberish } from "./types";

import {
  equalizeDecimals,
  from,
  isDnum,
  setDecimals,
  setValueDecimals,
} from "./dnum";
import { divideAndRound } from "./utils";

export function add(
  num1: Numberish,
  num2: Numberish,
  decimals?: Decimals,
): Dnum {
  const [num1_, num2_] = normalizePairAndDecimals(num1, num2, decimals);
  return setDecimals(
    [num1_[0] + num2_[0], num1_[1]],
    decimals ?? (isDnum(num1) ? num1[1] : num1_[1]),
  );
}

export function subtract(
  num1: Numberish,
  num2: Numberish,
  decimals?: Decimals,
): Dnum {
  const [num1_, num2_] = normalizePairAndDecimals(num1, num2, decimals);
  return setDecimals(
    [num1_[0] - num2_[0], num1_[1]],
    decimals ?? (isDnum(num1) ? num1[1] : num1_[1]),
  );
}

export function multiply(
  num1: Numberish,
  num2: Numberish,
  decimals?: Decimals,
): Dnum {
  const [num1_, num2_] = normalizePairAndDecimals(num1, num2, decimals);
  return setDecimals(
    [num1_[0] * num2_[0], num1_[1] * 2],
    decimals ?? (isDnum(num1) ? num1[1] : num1_[1]),
  );
}

export function divide(
  num1: Numberish,
  num2: Numberish,
  decimals?: Decimals,
): Dnum {
  const [num1_, num2_] = normalizePairAndDecimals(num1, num2, decimals);
  if (num2_[0] === 0n) {
    throw new Error("dnum: division by zero");
  }
  const value1 = setValueDecimals(num1_[0], Math.max(num1_[1], decimals ?? 0));
  const value2 = setValueDecimals(num2_[0], 0);
  return setDecimals(
    [divideAndRound(value1, value2), num1_[1]],
    decimals ?? (isDnum(num1) ? num1[1] : num1_[1]),
  );
}

export function remainder(
  num1: Numberish,
  num2: Numberish,
  decimals?: Decimals,
): Dnum {
  const [num1_, num2_] = normalizePairAndDecimals(num1, num2);
  return setDecimals(
    [num1_[0] % num2_[0], num1_[1]],
    decimals ?? (isDnum(num1) ? num1[1] : num1_[1]),
  );
}

export function compare(num1: Numberish, num2: Numberish): 1 | -1 | 0 {
  const [num1_, num2_] = normalizePairAndDecimals(num1, num2);
  return num1_[0] > num2_[0] ? 1 : num1_[0] < num2_[0] ? -1 : 0;
}

export function equal(num1: Numberish, num2: Numberish): boolean {
  const [num1_, num2_] = normalizePairAndDecimals(num1, num2);
  return num1_[0] === num2_[0];
}

export function greaterThan(num1: Numberish, num2: Numberish): boolean {
  const [num1_, num2_] = normalizePairAndDecimals(num1, num2);
  return num1_[0] > num2_[0];
}

export function lessThan(num1: Numberish, num2: Numberish): boolean {
  const [num1_, num2_] = normalizePairAndDecimals(num1, num2);
  return num1_[0] < num2_[0];
}

export function abs(num: Numberish, decimals?: Decimals): Dnum {
  const [valueIn, decimalsIn] = from(num);
  if (decimals === undefined) decimals = decimalsIn;

  let valueAbs = valueIn;
  if (valueAbs < 0n) {
    valueAbs = -valueAbs;
  }

  return setDecimals([valueAbs, decimalsIn], decimals);
}

export function floor(num: Numberish, decimals?: Decimals): Dnum {
  const [valueIn, decimalsIn] = from(num);
  if (decimals === undefined) decimals = decimalsIn;

  let whole = BigInt(String(valueIn).slice(0, -decimalsIn));
  const fraction = BigInt(String(valueIn).slice(-decimalsIn));
  if (whole < 0n && fraction > 0n) {
    whole -= 1n;
  }
  const numFloored: Dnum = [
    BigInt(String(whole) + "0".repeat(decimalsIn)),
    decimalsIn,
  ];

  return setDecimals(numFloored, decimals);
}

export function ceil(num: Numberish, decimals?: Decimals): Dnum {
  const minus1: Dnum = [-1n, 0];
  return multiply(floor(multiply(num, minus1)), minus1, decimals);
}

export function round(num: Numberish, decimals?: Decimals): Dnum {
  const numIn = from(num);
  return setDecimals(
    setDecimals(numIn, 0), // setDecimals() uses divideAndRound() internally
    decimals === undefined ? numIn[1] : decimals,
  );
}

// Converts a pair of Numberish into Dnum and equalize
// their decimals based on the highest precision found.
function normalizePairAndDecimals(
  num1: Numberish,
  num2: Numberish,
  decimals?: number,
) {
  const num1_ = from(num1);
  const num2_ = from(num2);

  if (num1_[1] < 0 || num2_[1] < 0) {
    throw new Error("dnum: decimals cannot be negative");
  }

  return equalizeDecimals(
    [num1_, num2_],
    Math.max(num1_[1], num2_[1], decimals ?? 0),
  );
}

import type { Decimals, Dnum, Numberish, Value } from "./types";

import fromExponential from "from-exponential";
import {
  abs,
  ceilToPower,
  divideAndRound,
  floorToPower,
  powerOfTen,
  roundToPower,
  splitNumber,
} from "./utils";

export function isDnum(value: unknown): value is Dnum {
  return (
    Array.isArray(value)
    && typeof value[0] === "bigint"
    && typeof value[1] === "number"
  );
}

// Matches:
//  - whole numbers (123)
//  - decimal numbers (1.23, .23)
//  - negative numbers (-123, -1.23, -.23)
const NUM_RE = /^-?(?:[0-9]+|(?:[0-9]*(?:\.[0-9]+)))$/;

// Based on ethers parseFixed():
// https://github.com/ethers-io/ethers.js/blob/8b62aeff9cce44cbd16ff41f8fc01ebb101f8265/packages/bignumber/src.ts/fixednumber.ts#L70
export function from(
  value: Numberish,
  decimals: number | true = true,
): Dnum {
  if (isDnum(value)) {
    return setDecimals(value, decimals === true ? value[1] : decimals);
  }

  value = String(value);

  if (value.includes("e")) {
    value = fromExponential(value);
  }

  if (!value.match(NUM_RE)) {
    throw new Error(`dnum: incorrect number (${value})`);
  }

  const negative = value.startsWith("-");
  if (negative) {
    value = value.slice(1);
  }

  const parts = splitNumber(value);
  const whole = parts[0];
  let fraction = parts[1];

  if (decimals === true) {
    decimals = fraction === "0" ? 0 : fraction.length;
  }

  // truncate according to decimals
  fraction = fraction.slice(0, decimals);

  // pad fraction with trailing zeros
  fraction = fraction + "0".repeat(decimals - fraction.length);

  const result = (
    BigInt(whole) * powerOfTen(decimals) + BigInt(fraction)
  ) * (
    negative ? -1n : 1n
  );

  return [result, decimals];
}

export function setValueDecimals(
  value: Value,
  decimalsDiff: Decimals,
  options: { round?: boolean } = {},
): Value {
  options.round ??= true;

  if (decimalsDiff > 0) {
    return value * powerOfTen(decimalsDiff);
  }

  if (decimalsDiff < 0) {
    return options.round
      ? divideAndRound(value, powerOfTen(-decimalsDiff))
      : value / powerOfTen(-decimalsDiff);
  }

  return value;
}

export function setDecimals(
  value: Dnum,
  decimals: Decimals,
  options: { round?: boolean } = {},
): Dnum {
  options.round ??= true;

  if (value[1] === decimals) {
    return value;
  }

  if (value[1] < 0 || decimals < 0) {
    throw new Error("dnum: decimals cannot be negative");
  }

  const decimalsDiff = decimals - value[1];
  return [
    setValueDecimals(value[0], decimalsDiff, options),
    decimals,
  ];
}

export function equalizeDecimals(nums: Dnum[], decimals?: number): Dnum[] {
  const decimals_ = decimals
    ?? Math.max(...nums.map(([, decimals]) => decimals), 0);
  return nums.map((num) => setDecimals(num, decimals_));
}

export function toJSON([value, decimals]: Dnum) {
  return JSON.stringify([String(value), decimals]);
}

export function fromJSON(jsonValue: string): Dnum {
  const [value, decimals] = JSON.parse(jsonValue);
  return [BigInt(value), decimals];
}

export function toParts(
  dnum: Dnum,
  optionsOrDigits:
    | {
      digits?: number; // defaults to decimals
      trailingZeros?: boolean;
      decimalsRounding?: "ROUND_HALF" | "ROUND_UP" | "ROUND_DOWN";
    }
    | number = {},
): [
  whole: bigint, // always positive
  fraction: string | null,
] {
  const [value, decimals] = dnum;

  // options.digits can also be passed directly as the second argument
  const options = typeof optionsOrDigits === "number"
    ? { digits: optionsOrDigits }
    : optionsOrDigits;

  const {
    digits = decimals,
    trailingZeros,
    decimalsRounding,
  } = options;

  const decimalsDivisor = powerOfTen(decimals);

  let whole = value / decimalsDivisor;
  const fractionValue = abs(value % decimalsDivisor);

  let roundFn = (
    decimalsRounding === "ROUND_UP"
      ? ceilToPower
      : decimalsRounding === "ROUND_DOWN"
      ? floorToPower
      : roundToPower
  );

  let fraction = String(
    roundFn(
      BigInt(
        // prefix with 1 to keep the leading zeros
        "1"
          // leading zeros
          + "0".repeat(
            Math.max(
              0,
              String(decimalsDivisor).length - String(fractionValue).length - 1,
            ),
          )
          // non zero numbers
          + String(fractionValue),
      ),
      powerOfTen(Math.max(0, decimals - digits)),
    ),
  );

  // if the 1 prefix has changed to 2, it means that the
  // rounding caused the whole part to be incremented
  if (fraction.startsWith("2")) {
    whole += 1n;
  }

  // remove the leading 1 and extra decimal places (see above)
  fraction = fraction.slice(1, digits + 1);

  // trim or pad with trailing zeros
  fraction = trailingZeros
    ? fraction.padEnd(digits, "0")
    : fraction.replace(/0+$/, "");

  return [
    abs(whole),
    fraction === "" || (BigInt(fraction) === 0n && !trailingZeros)
      ? null
      : fraction,
  ];
}

export function toNumber(
  value: Dnum,
  optionsOrDigits: Parameters<typeof toParts>[1],
) {
  const [whole, fraction] = toParts(value, optionsOrDigits);
  return Number(
    (value[0] >= 0n ? "" : "-")
      + whole
      + (fraction ? `.${fraction}` : ""),
  );
}

